CREATE TEMP TABLE afg_profiles ON COMMIT DROP AS SELECT id,profile_version,updated_at FROM jsonb_populate_recordset(null::public.teams,'[{"id":"3a9c1f75-ecbe-4c05-85b9-bacfd65fb7ff","competition_season_id":"62ce7ec9-459e-4acf-bec5-c6734a3199ef","legacy_id":"mon-afg","name":"AFG","status":"active","kit_colour":"#2F80ED","standings_eligible":true,"profile_version":3,"updated_at":"2026-10-15T08:58:03.138018+00:00"},{"id":"b7102a75-a3ad-488c-b16e-f6da36e7f7ba","competition_season_id":"be008d39-f175-45c1-a232-2148d84b1cf9","legacy_id":"wed-afg","name":"AFG","status":"active","kit_colour":"#2F80ED","standings_eligible":true,"profile_version":1,"updated_at":"2026-10-10T19:11:23.617699+00:00"}]'::jsonb);
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM public.fixture_change_sets WHERE competition_season_id IN('62ce7ec9-459e-4acf-bec5-c6734a3199ef','be008d39-f175-45c1-a232-2148d84b1cf9')AND status IN('draft','pending_review'))THEN RAISE EXCEPTION 'Pending fixture work requires review';END IF;
 IF EXISTS(SELECT 1 FROM afg_profiles p LEFT JOIN public.teams t USING(id)WHERE t.id IS NULL OR t.name<>'AFG'OR t.status<>'active'OR NOT t.standings_eligible OR t.profile_version<>p.profile_version OR t.updated_at<>p.updated_at)THEN RAISE EXCEPTION 'AFG profile baseline changed';END IF;
 IF EXISTS(SELECT 1 FROM public.team_kickoff_preferences WHERE team_id IN('3a9c1f75-ecbe-4c05-85b9-bacfd65fb7ff','b7102a75-a3ad-488c-b16e-f6da36e7f7ba'))THEN RAISE EXCEPTION 'AFG preferences changed; reconcile first';END IF;
 IF (SELECT count(*)FROM afg_changes)<>20 OR EXISTS(SELECT 1 FROM afg_baseline b LEFT JOIN public.fixtures f USING(id)WHERE row(f.id,f.competition_season_id,f.round_number,f.match_date,f.kickoff_time,f.court,f.home_team_id,f.away_team_id,f.publication_state,f.schedule_status,f.schedule_version,f.updated_at)IS DISTINCT FROM row(b.id,b.competition_season_id,b.round_number,b.match_date,b.kickoff_time,b.court,b.home_team_id,b.away_team_id,b.publication_state,b.schedule_status,b.schedule_version,b.updated_at))THEN RAISE EXCEPTION 'Fixture baseline changed';END IF;
 IF EXISTS(SELECT 1 FROM public.result_versions WHERE fixture_id IN(SELECT id FROM afg_changes))THEN RAISE EXCEPTION 'Affected future fixture has result work';END IF;
END $$;
CREATE TEMP TABLE afg_protected ON COMMIT DROP AS select 'results'kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]'))hash from public.result_versions x where true
union all
select 'fixtures'kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]'))hash from public.fixtures x where id not in(select id from afg_changes)
union all
select 'teams'kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]'))hash from public.teams x where id not in('3a9c1f75-ecbe-4c05-85b9-bacfd65fb7ff','b7102a75-a3ad-488c-b16e-f6da36e7f7ba')
union all
select 'notes'kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by team_id)::text,'[]'))hash from public.team_fixture_notes x where team_id not in('3a9c1f75-ecbe-4c05-85b9-bacfd65fb7ff','b7102a75-a3ad-488c-b16e-f6da36e7f7ba')
union all
select 'preferences'kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]'))hash from public.team_kickoff_preferences x where team_id not in('3a9c1f75-ecbe-4c05-85b9-bacfd65fb7ff','b7102a75-a3ad-488c-b16e-f6da36e7f7ba')
union all
select 'adjustments'kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]'))hash from public.standing_adjustments x where true;
CREATE TEMP TABLE afg_audit_before ON COMMIT DROP AS SELECT id,to_jsonb(a)preserved FROM public.admin_audit_log a;
CREATE TEMP TABLE afg_fixture_before ON COMMIT DROP AS SELECT id,to_jsonb(f)-'kickoff_time'-'court'-'updated_at'-'schedule_version'preserved,schedule_version FROM public.fixtures f WHERE id IN(SELECT id FROM afg_changes);
CREATE TEMP TABLE afg_team_before ON COMMIT DROP AS SELECT id,to_jsonb(t)-'profile_version'-'updated_at'preserved FROM public.teams t WHERE id IN('3a9c1f75-ecbe-4c05-85b9-bacfd65fb7ff','b7102a75-a3ad-488c-b16e-f6da36e7f7ba');
INSERT INTO public.team_kickoff_preferences(team_id,kickoff_time,classification)SELECT t.id,tm::time,'required'FROM afg_profiles t CROSS JOIN unnest(array['19:00','19:40','20:20'])tm;
INSERT INTO public.team_fixture_notes(team_id,notes)SELECT id,'Current organiser rule, 10 November 2026: AFG cannot play at 21:00 on Monday or Wednesday (hard). Allowed general kickoff times: 19:00, 19:40, 20:20. EXPLICIT WEDNESDAY EXCEPTION: AFG must play Umoja Stars at 21:00 on 25 November 2026 and 24 March 2027; Umoja remains strictly 21:00. The exception does not allow 21:00 against other opponents. This supersedes earlier any-time availability.' FROM afg_profiles ON CONFLICT(team_id)DO UPDATE SET notes=excluded.notes||E'

Earlier scheduling context (historical; superseded where conflicting):
'||public.team_fixture_notes.notes;
UPDATE public.teams SET profile_version=profile_version+1 WHERE id IN('3a9c1f75-ecbe-4c05-85b9-bacfd65fb7ff','b7102a75-a3ad-488c-b16e-f6da36e7f7ba');
-- Standard publication swap technique: free old slots within this atomic transaction.
UPDATE public.fixtures SET publication_state='draft'WHERE id IN(SELECT id FROM afg_changes);
UPDATE public.fixtures f SET kickoff_time=c.kickoff_time,court=c.court,publication_state='published'FROM afg_changes c WHERE c.id=f.id;
DO $$ BEGIN
 IF (SELECT count(*)FROM public.team_kickoff_preferences WHERE team_id IN('3a9c1f75-ecbe-4c05-85b9-bacfd65fb7ff','b7102a75-a3ad-488c-b16e-f6da36e7f7ba')AND classification='required'AND kickoff_time IN('19:00','19:40','20:20'))<>6 THEN RAISE EXCEPTION 'AFG preference verification failed';END IF;
 IF EXISTS(SELECT 1 FROM public.fixtures f JOIN public.teams h ON h.id=f.home_team_id JOIN public.teams a ON a.id=f.away_team_id WHERE f.competition_season_id IN('62ce7ec9-459e-4acf-bec5-c6734a3199ef','be008d39-f175-45c1-a232-2148d84b1cf9')AND f.publication_state='published'AND f.schedule_status='scheduled'AND f.match_date>='2026-11-10'AND f.kickoff_time='21:00'AND(h.name='AFG'OR a.name='AFG')AND NOT(f.competition_season_id='be008d39-f175-45c1-a232-2148d84b1cf9'AND(h.name='Umoja Stars'OR a.name='Umoja Stars')))THEN RAISE EXCEPTION 'AFG still has an unapproved future 21:00 game';END IF;
 IF (SELECT count(*)FROM public.fixtures f JOIN public.teams h ON h.id=f.home_team_id JOIN public.teams a ON a.id=f.away_team_id WHERE f.competition_season_id='be008d39-f175-45c1-a232-2148d84b1cf9'AND f.publication_state='published'AND f.schedule_status='scheduled'AND f.match_date IN('2026-11-25','2027-03-24')AND f.kickoff_time='21:00'AND array[h.name,a.name]@>array['AFG','Umoja Stars'])<>2 THEN RAISE EXCEPTION 'Approved Umoja exceptions changed';END IF;
 IF EXISTS(SELECT 1 FROM afg_fixture_before b JOIN public.fixtures f USING(id)WHERE b.preserved IS DISTINCT FROM to_jsonb(f)-'kickoff_time'-'court'-'updated_at'-'schedule_version'OR f.schedule_version<>b.schedule_version+2)THEN RAISE EXCEPTION 'Non-slot fixture field or version changed';END IF;
 IF EXISTS(SELECT 1 FROM afg_team_before b JOIN public.teams t USING(id)WHERE b.preserved IS DISTINCT FROM to_jsonb(t)-'profile_version'-'updated_at')THEN RAISE EXCEPTION 'Team identity or record changed';END IF;
 IF EXISTS(SELECT 1 FROM afg_audit_before b LEFT JOIN public.admin_audit_log a USING(id)WHERE b.preserved IS DISTINCT FROM to_jsonb(a))THEN RAISE EXCEPTION 'Existing audit record changed';END IF;
 IF EXISTS(SELECT 1 FROM afg_protected p JOIN(select 'results'kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]'))hash from public.result_versions x where true
union all
select 'fixtures'kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]'))hash from public.fixtures x where id not in(select id from afg_changes)
union all
select 'teams'kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]'))hash from public.teams x where id not in('3a9c1f75-ecbe-4c05-85b9-bacfd65fb7ff','b7102a75-a3ad-488c-b16e-f6da36e7f7ba')
union all
select 'notes'kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by team_id)::text,'[]'))hash from public.team_fixture_notes x where team_id not in('3a9c1f75-ecbe-4c05-85b9-bacfd65fb7ff','b7102a75-a3ad-488c-b16e-f6da36e7f7ba')
union all
select 'preferences'kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]'))hash from public.team_kickoff_preferences x where team_id not in('3a9c1f75-ecbe-4c05-85b9-bacfd65fb7ff','b7102a75-a3ad-488c-b16e-f6da36e7f7ba')
union all
select 'adjustments'kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]'))hash from public.standing_adjustments x where true)a USING(kind)WHERE p.hash IS DISTINCT FROM a.hash)THEN RAISE EXCEPTION 'Protected data changed';END IF;
END $$;
COMMIT;
